import 'package:flutter/foundation.dart';import '../preference_sync/preference_protocol.dart' show PreferenceScope,canonicalPreference;import 'work_module_model.dart';
class WorkQuery {final String search;final int offset;const WorkQuery([this.search='',this.offset=0]);}
class WorkReceipt {final String itemId,action;final int version;final Map<String,String> expected;const WorkReceipt(this.itemId,this.version,this.action,this.expected);}
abstract interface class WorkPort {Future<Object?> read(WorkQuery query);Future<WorkReceipt> mutate(WorkCommand command,String requestId);Future<Object?> readItem(String id);void dispose();}
class WorkModuleSession extends ChangeNotifier {final PreferenceScope scope;final String module;final WorkPort? port;final String Function()? requestId;WorkSnapshot? snapshot;WorkQuery query=const WorkQuery();String status;int generation=0;bool dead=false,busy=false;WorkCommand? pending;String? pendingKey;
 WorkModuleSession(this.scope,this.module,{this.port,this.requestId}):status=port==null?'unavailable':'idle'{if(!['calendar','contacts','tasks','notes','board','mailbox','messenger','notifications','files'].contains(module))throw const WorkFailure('invalid');}
 Future<void> load([WorkQuery? next])async{if(dead||port==null||busy)return;final q=next??query;if(q.search.length>100||q.offset<0||q.offset>100000)throw const WorkFailure('invalid');query=q;final g=++generation;status='loading';snapshot=null;notifyListeners();try{final raw=await port!.read(query);if(dead||g!=generation)return;snapshot=WorkSnapshot.fromJson(raw,scope,module);status='ready';}catch(e){if(dead||g!=generation)return;status=e is WorkFailure?e.code:'error';}notifyListeners();}
 Future<void> submit(String id,String action,Map<String,String> fields,{int? expectedVersion})async{if(dead||busy||port==null||snapshot==null||status=='loading')throw const WorkFailure('unavailable');final rows=snapshot!.items.where((i)=>i.id==id).toList();if(rows.length!=1)throw const WorkFailure('denied',403);final item=rows.single;if(expectedVersion!=null&&expectedVersion!=item.version)throw const WorkFailure('conflict',409);final command=validateWorkCommand(item,action,fields);if(pending!=null&&canonicalPreference(pending!.toJson())!=canonicalPreference(command.toJson()))throw const WorkFailure('conflict',409);if(pending==null){final key=requestId?.call();if(key==null||!RegExp(r'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$',caseSensitive:false).hasMatch(key))throw const WorkFailure('invalid');pending=command;pendingKey=key;}await _send();}
 Future<void> retryPending()async{if(dead||busy||pending==null||port==null)throw const WorkFailure('unavailable');await _send();}
 Future<void> _send()async{busy=true;final g=++generation,command=pending!;status='saving';notifyListeners();try{final receipt=await port!.mutate(command,pendingKey!);if(dead||g!=generation)return;if(receipt.itemId!=command.itemId||receipt.action!=command.action||receipt.version!=command.version+1||receipt.expected.keys.any((k)=>!['title','body','date','lane','meta'].contains(k)))throw const WorkFailure('error',502);final raw=await port!.readItem(receipt.itemId);if(dead||g!=generation)return;final verified=WorkSnapshot.fromJson(raw,scope,module),items=verified.items.where((i)=>i.id==receipt.itemId).toList();if(items.length!=1||items.single.version!=receipt.version||receipt.expected.entries.any((e)=>items.single.toJson()[e.key]!=e.value))throw const WorkFailure('conflict',409);final updated=snapshot!.toJson();updated['items']=snapshot!.items.map((i)=>(i.id==receipt.itemId?items.single:i).toJson()).toList();snapshot=WorkSnapshot.fromJson(updated,scope,module);pending=null;pendingKey=null;status='success';}catch(e){if(dead||g!=generation)return;if(e is WorkFailure&&[400,403,404,409].contains(e.status)){pending=null;pendingKey=null;}status=e is WorkFailure?e.code:'error';if(status=='denied')snapshot=null;}finally{busy=false;}notifyListeners();if(['error','denied','conflict','invalid'].contains(status))throw WorkFailure(status);}
 @override void dispose(){if(dead)return;dead=true;generation++;port?.dispose();snapshot=null;pending=null;status='disposed';super.dispose();}}
